                [LibraryImport("khaos")]
                internal static partial void Start();
            }
            """;

        AnalyzerResult result = await AnalyzerRunner<InteropEntryPointAnalyzer>.RunAsync(source);

        await result.CompilationErrors.Should().BeEmpty();
        await result.Located.Should().BeEmpty();
    }

    [Test]
    public async Task MethodWithoutLibraryImportShouldReportNothing()
    {
        const string source = """
            namespace KappaDuck.Khaos.Interop.SDL;

            internal static class Errors
            {
                internal static void ThrowIfFailed(byte result)
                {
                }
            }
            """;

        AnalyzerResult result = await AnalyzerRunner<InteropEntryPointAnalyzer>.RunAsync(source);

        await result.CompilationErrors.Should().BeEmpty();
        await result.Located.Should().BeEmpty();
    }

    [Test]
    public async Task CompilationWithoutLibraryImportShouldReportNothing()
    {
        const string source = """
            namespace KappaDuck.Khaos.Interop.SDL;

            internal static partial class SDL3
            {
                [System.Runtime.InteropServices.LibraryImport("SDL3")]
                internal static partial bool Quit();
            }
            """;

        AnalyzerResult result = await AnalyzerRunner<InteropEntryPointAnalyzer>.RunAsync(TestCompilation.WithoutReferences(source));

        await result.Located.Should().BeEmpty();
    }
}
